sources.api_contacts.vibe:
type Contact = { id: int, email: string, active: bool, ... }
type Recipient = { id: string, email: string }
def recipients(raw: string) -> string
  contacts = JSON.parse_as(raw, array<Contact>)
  selected = contacts.select { |contact| contact["active"] }
  rows: array<Recipient> = selected.map { |contact|
    { id: contact["id"].to_s, email: contact["email"].strip.downcase }
  }
  JSON.stringify(rows)
end

sources.api_invoice.vibe:
type Invoice = { id: string, customer: { name: string }, lines: array<{ sku: string, cents: int, quantity: int }> }
def export_invoice(raw: string) -> string
  invoice = JSON.parse_as(raw, Invoice)
  total = invoice["lines"].sum { |line| line["cents"] * line["quantity"] }
  JSON.stringify({ id: invoice["id"], customer: invoice["customer"]["name"], total_cents: total })
end

sources.page_numbers.vibe:
type Page = { items: array<{ id: int }>, has_more: bool }
def collect_pages(pages: array<string>) -> array<int>
  ids: array<int> = []
  index = 0
  loop {
    page = JSON.parse_as(pages.fetch(index), Page)
    page["items"].each { |item| ids << item["id"] }
    break if !page["has_more"]
    index += 1
  }
  ids
end

sources.delivery_batch.vibe:
type Delivery = { recipient: string, ok: bool, detail: string }
def deliver_all(recipients: array<string>, &send: string -> string) -> array<Delivery>
  recipients.map { |recipient|
    begin
      { recipient: recipient, ok: true, detail: yield(recipient) }
    rescue RuntimeError => error
      { recipient: recipient, ok: false, detail: error.message }
    end
  }
end

sources.regional_totals.vibe:
type Order = { region: string, cents: int }
def totals(orders: array<Order>) -> hash<string, int>
  orders.group_by { |order| order["region"] }.transform_values { |group|
    group.sum { |order| order["cents"] }
  }
end

sources.duration_report.vibe:
def delay_report(delays: array<string>) -> { seconds: int, iso: string }
  total = delays.map { |delay| Duration.parse(delay) }.sum(0.seconds)
  { seconds: total.to_i, iso: total.iso8601 }
end

