type Line = { unit: money, quantity: int }
def invoice(lines: array<Line>, currency: string) -> string
  total = lines.sum(money_cents(0, currency)) { |line| line["unit"] * line["quantity"] }
  JSON.stringify({ cents: total.cents, currency: total.currency, display: total.to_s })
end

sources.work_queue.vibe:
type Job = { id: string, attempts: int }
class Queue
  @jobs: array<Job> = []
  def add(job: Job)
    @jobs.push(job)
  end
  def take -> Job?
    @jobs.shift
  end
  def snapshot -> array<Job>
    @jobs
  end
end
def drain(jobs: array<Job>) -> array<string>
  queue = Queue.new
  jobs.each { |job| queue.add(job) }
  ids: array<string> = []
  loop {
    job = queue.take
    break if job == nil
    ids << job["id"]
  }
  ids
end

sources.log_parser.vibe:
type Entry = { level: string, service: string, ms: int }
def parse_line(line: string) -> Entry?
  match = line.match(/^(INFO|ERROR) service=([a-z]+) ms=([0-9]+)$/)
  return nil if match == nil
  { level: match[1].as(string), service: match[2].as(string), ms: match[3].as(string).to_i }
end

sources.user_index.vibe:
type User = { id: string, name: string }
def names(users: array<User>, ids: array<string>) -> array<string>
  index: hash<string, User> = users.to_h { |user| [user["id"], user] }
  ids.map { |id|
    user = index[id]
    user == nil ? "unknown" : user["name"]
  }
end

sources.dedup_events.vibe:
type Event = { id: string, body: string }
def unique_bodies(events: array<Event>) -> array<string>
  events.uniq { |event| event["id"] }.map { |event| event["body"] }
end

